B=[
('السَّهْبُ وَالْقِسْطَنْطِينِيَّةُ','Bozkır ve Kostantiniyye',[
('عَبَرَ الْبَحْرَ الْأَسْوَدَ إِلَى بِلَادِ الْقَبْجَاقِ، وَهِيَ سُهُوبٌ وَاسِعَةٌ لَا جَبَلَ فِيهَا وَلَا شَجَرَ.','Karadeniz’i aşarak dağı ve ağacı olmayan geniş bozkırlar olan Kıpçak diyarına geçti.'),
('وَرَأَى النَّاسَ يَسْكُنُونَ فِي بُيُوتٍ عَلَى عَرَبَاتٍ تَجُرُّهَا الْخَيْلُ، كَأَنَّهَا مَدِينَةٌ تَمْشِي.','İnsanların atların çektiği arabalar üzerindeki evlerde yaşadığını gördü; sanki yürüyen bir şehirdi.'),
('وَلَقِيَ السُّلْطَانَ مُحَمَّدَ أُوزْبَكَ خَانَ، فَأَكْرَمَهُ.','Sultan Muhammed Özbek Han’la görüştü; o da ona ikram etti.'),
('وَكَانَتْ إِحْدَى زَوْجَاتِ السُّلْطَانِ بِنْتَ إِمْبِرَاطُورِ الْقِسْطَنْطِينِيَّةِ، فَسَافَرَ مَعَهَا لِزِيَارَةِ أَبِيهَا.','Sultanın eşlerinden biri Kostantiniyye imparatorunun kızıydı; Battûta babasını ziyaret etmek için onunla yolculuk etti.'),
('فَدَخَلَ الْقِسْطَنْطِينِيَّةَ، وَرَأَى كَنِيسَتَهَا الْعَظِيمَةَ آيَا صُوفْيَا مِنَ الْخَارِجِ.','Kostantiniyye’ye girdi ve büyük kilisesi Ayasofya’yı dışarıdan gördü.'),
('وَتَعَجَّبَ مِنْ سَعَةِ الْمَدِينَةِ وَأَسْوَارِهَا، وَمِنْ كَثْرَةِ الرُّهْبَانِ فِيهَا.','Şehrin genişliğine, surlarına ve içindeki rahiplerin çokluğuna şaştı.')]),
('الْهِنْدُ','Hindistan',[
('ثُمَّ عَبَرَ جِبَالَ الْهِنْدُوكُوشِ الْعَالِيَةَ، فِي ثَلْجٍ وَبَرْدٍ شَدِيدٍ.','Sonra yüksek Hindukuş dağlarını şiddetli kar ve soğuk içinde aştı.'),
('وَوَصَلَ إِلَى دِهْلِي، وَكَانَ سُلْطَانُهَا مُحَمَّدُ بْنُ تُغْلُقَ.','Delhi’ye vardı; sultanı Muhammed b. Tuğluk idi.'),
('قَالَ ابْنُ بَطُّوطَةَ: «هَذَا الْمَلِكُ أَحَبُّ النَّاسِ فِي إِسْدَاءِ الْعَطَايَا وَسَفْكِ الدِّمَاءِ.»','İbn Battûta dedi ki: “Bu hükümdar, insanlar içinde hem bağış yapmayı hem kan dökmeyi en çok seven kişidir.”'),
('فَجَعَلَهُ السُّلْطَانُ قَاضِيًا فِي دِهْلِي، وَأَعْطَاهُ مَالًا كَثِيرًا.','Sultan onu Delhi’de kadı yaptı ve ona çok mal verdi.'),
('وَبَقِيَ هُنَاكَ ثَمَانِيَ سِنِينَ، يَخَافُ غَضَبَ السُّلْطَانِ كُلَّ يَوْمٍ.','Orada sekiz yıl kaldı; her gün sultanın öfkesinden korkuyordu.'),
('ثُمَّ أَرْسَلَهُ السُّلْطَانُ سَفِيرًا إِلَى مَلِكِ الصِّينِ، وَمَعَهُ هَدَايَا عَظِيمَةٌ.','Sonra sultan onu büyük hediyelerle Çin hükümdarına elçi olarak gönderdi.')]),
('الْغَرَقُ وَجُزُرُ ذِيبَةَ الْمَهَلِ','Batış ve Maldiv adaları',[
('وَلَكِنَّ الْمَرَاكِبَ الَّتِي فِيهَا الْهَدَايَا غَرِقَتْ فِي عَاصِفَةٍ قُرْبَ سَاحِلِ الْهِنْدِ.','Ama hediyelerin bulunduğu gemiler Hindistan kıyısı yakınında bir fırtınada battı.'),
('فَبَقِيَ ابْنُ بَطُّوطَةَ عَلَى السَّاحِلِ، لَيْسَ مَعَهُ إِلَّا ثِيَابُهُ وَسَجَّادَتُهُ.','İbn Battûta kıyıda, yanında elbiselerinden ve seccadesinden başka bir şey olmadan kaldı.'),
('فَخَافَ أَنْ يَرْجِعَ إِلَى السُّلْطَانِ، فَسَافَرَ إِلَى جُزُرِ ذِيبَةِ الْمَهَلِ.','Sultana dönmekten korktu ve Maldiv adalarına yolculuk etti.'),
('وَهِيَ جُزُرٌ صَغِيرَةٌ كَثِيرَةٌ، أَهْلُهَا مُسْلِمُونَ أَهْلُ صَلَاحٍ وَدِيَانَةٍ.','Bunlar çok sayıda küçük adadır; halkı salih ve dindar Müslümanlardır.'),
('فَجَعَلُوهُ قَاضِيًا، وَحَاوَلَ أَنْ يُقِيمَ فِيهِمُ الشَّرِيعَةَ بِشِدَّةٍ.','Onu kadı yaptılar; o da aralarında şeriatı sertlikle uygulamaya çalıştı.'),
('وَتَعَجَّبَ مِنْ نِسَائِهَا، وَمِنْ كَثْرَةِ جَوْزِ النَّارَجِيلِ وَالسَّمَكِ.','Kadınlarına, hindistan cevizinin ve balığın bolluğuna şaştı.')]),
('الصِّينُ','Çin',[
('ثُمَّ وَصَلَ أَخِيرًا إِلَى الصِّينِ، فَقَالَ: «إِقْلِيمُ الصِّينِ مُتَّسِعٌ، كَثِيرُ الْخَيْرَاتِ وَالْفَوَاكِهِ وَالزَّرْعِ وَالذَّهَبِ وَالْفِضَّةِ.»','Sonra nihayet Çin’e vardı ve dedi ki: “Çin bölgesi geniştir; hayırları, meyveleri, ekinleri, altını ve gümüşü boldur.”'),
('وَتَعَجَّبَ مِنْ أَنَّ أَهْلَهَا يَتَبَايَعُونَ بِقِطَعٍ مِنَ الْكَاغَدِ بَدَلًا مِنَ الدَّرَاهِمِ.','Halkının dirhem yerine kâğıt parçalarıyla alışveriş etmesine şaştı.'),
('وَرَأَى صِنَاعَةَ الْفَخَّارِ الصِّينِيِّ، وَقَالَ: «لَا يُصْنَعُ إِلَّا فِي الصِّينِ.»','Çin porseleninin yapımını gördü ve dedi ki: “Yalnız Çin’de yapılır.”'),
('وَقَالَ: «الصِّينُ آمَنُ الْبِلَادِ لِلْمُسَافِرِ؛ يُسَافِرُ الرَّجُلُ وَحْدَهُ مَسِيرَةَ تِسْعَةِ أَشْهُرٍ وَمَعَهُ الْمَالُ الْكَثِيرُ فَلَا يَخَافُ.»','Dedi ki: “Çin, yolcu için ülkelerin en güvenlisidir; insan yanında çok malla dokuz aylık yolu tek başına gider ve korkmaz.”'),
('وَلَكِنَّهُ لَمْ يُحِبَّ كُلَّ مَا رَأَى؛ فَقَدْ كَانَ قَلْبُهُ يَشْتَاقُ إِلَى بِلَادِ الْإِسْلَامِ.','Ama gördüğü her şeyi sevmedi; çünkü kalbi İslâm diyarını özlüyordu.'),
('فَكَانَ إِذَا لَقِيَ الْمُسْلِمِينَ هُنَاكَ فَرِحَ بِهِمْ كَمَا يَفْرَحُ بِأَهْلِهِ.','Orada Müslümanlarla karşılaşınca ailesine sevinir gibi sevinirdi.')]),
('الْعَوْدَةُ','Dönüş',[
('ثُمَّ رَجَعَ إِلَى الْغَرْبِ بَعْدَ أَرْبَعٍ وَعِشْرِينَ سَنَةً مِنْ خُرُوجِهِ.','Sonra çıkışından yirmi dört yıl sonra Mağrib’e döndü.'),
('وَفِي الطَّرِيقِ عَلِمَ أَنَّ أَبَاهُ قَدْ مَاتَ قَبْلَ خَمْسَ عَشْرَةَ سَنَةً.','Yolda babasının on beş yıl önce öldüğünü öğrendi.'),
('وَلَمَّا وَصَلَ إِلَى بِلَادِهِ، عَلِمَ أَنَّ أُمَّهُ قَدْ تُوُفِّيَتْ بِالطَّاعُونِ قَبْلَ وُصُولِهِ بِأَيَّامٍ.','Memleketine varınca annesinin, o varmadan günler önce vebadan öldüğünü öğrendi.'),
('فَبَكَى عَلَيْهَا، وَزَارَ قَبْرَهَا.','Ona ağladı ve kabrini ziyaret etti.'),
('ثُمَّ لَمْ يَسْكُنْ قَلْبُهُ، فَسَافَرَ إِلَى الْأَنْدَلُسِ، ثُمَّ عَبَرَ الصَّحْرَاءَ الْكُبْرَى إِلَى مَالِي.','Sonra kalbi rahat etmedi; Endülüs’e gitti, sonra Büyük Sahra’yı aşıp Mali’ye ulaştı.'),
('وَهُنَاكَ رَأَى مَمْلَكَةً غَنِيَّةً بِالذَّهَبِ، وَأَهْلُهَا حَرِيصُونَ عَلَى الصَّلَاةِ وَحِفْظِ الْقُرْآنِ.','Orada altınca zengin bir krallık gördü; halkı namaza ve Kur’an ezberlemeye çok düşkündü.')]),
('الْكِتَابُ','Kitap',[
('وَلَمَّا رَجَعَ إِلَى فَاسَ، أَمَرَ السُّلْطَانُ أَبُو عِنَانٍ أَنْ تُكْتَبَ رِحْلَتُهُ.','Fas’a dönünce Sultan Ebû İnân yolculuğunun yazılmasını emretti.'),
('فَأَمْلَاهَا عَلَى كَاتِبٍ أَدِيبٍ اسْمُهُ ابْنُ جُزَيٍّ، فَكَتَبَهَا بِأُسْلُوبٍ جَمِيلٍ.','Onu İbn Cüzeyy adında edip bir kâtibe yazdırdı; o da onu güzel bir üslupla yazdı.'),
('وَسُمِّيَ الْكِتَابُ: «تُحْفَةَ النُّظَّارِ فِي غَرَائِبِ الْأَمْصَارِ وَعَجَائِبِ الْأَسْفَارِ».','Kitaba “Şehirlerin garipliklerine ve yolculukların acayipliklerine bakanlar için armağan” adı verildi.'),
('وَتُوُفِّيَ ابْنُ بَطُّوطَةَ فِي الْمَغْرِبِ، بَعْدَ أَنْ رَأَى مِنَ الدُّنْيَا مَا لَمْ يَرَهُ أَحَدٌ فِي زَمَانِهِ.','İbn Battûta, zamanında kimsenin görmediği kadar dünyayı gördükten sonra Mağrib’de vefat etti.'),
('وَبَقِيَ كِتَابُهُ إِلَى الْيَوْمِ يُقْرَأُ فِي الشَّرْقِ وَالْغَرْبِ، وَيُعَلِّمُ النَّاسَ أَنَّ الْأَرْضَ وَاسِعَةٌ، وَأَنَّ النَّاسَ إِخْوَةٌ.','Kitabı bugüne kadar doğuda ve batıda okunuyor ve insanlara yeryüzünün geniş, insanların kardeş olduğunu öğretiyor.')]),
]
